def join_path(self, *args):
    parts = []
    for arg in args:
        arg = self._unquote(arg).replace('/', '\\')
        # Check if the argument is a UNC path
        if arg.startswith('\\\\'):
            parts.append(arg)
        else:
            parts.extend([a for a in arg.split('\\') if a])
    path = '\\'.join(parts)
    if path.startswith('~'):
        return path
    # If the path starts with '\\', it's a UNC path, so add another '\\' at the beginning
    if path.startswith('\\\\'):
        return path
    return path
