def join_path(self, *args):
    parts = []
    for arg in args:
        arg = self._unquote(arg).replace('/', '\\')
        # Check if the argument starts with '\\\\' (indicating a UNC path)
        if arg.startswith('\\\\'):
            parts.append(arg)
        else:
            parts.extend([a for a in arg.split('\\') if a])
    path = '\\'.join(parts)
    if path.startswith('~'):
        return path
    return path
